WITH parsed AS (SELECT contact_id,date_text,coalesce(CASE WHEN regexp_full_match(trim(date_text),'[0-9]{4}-[0-9]{2}-[0-9]{2}') THEN try_strptime(trim(date_text),'%Y-%m-%d') END,CASE WHEN regexp_full_match(trim(date_text),'[0-9]{2}/[0-9]{2}/[0-9]{4}') THEN try_strptime(trim(date_text),'%d/%m/%Y') END,CASE WHEN regexp_full_match(trim(date_text),'[0-9]{2} [A-Za-z]{3} [0-9]{4}') THEN try_strptime(trim(date_text),'%d %b %Y') END)::DATE AS parsed_date FROM raw_contacts) SELECT contact_id,parsed_date,CASE WHEN date_text IS NULL THEN 'missing' WHEN parsed_date IS NULL THEN 'invalid' ELSE 'valid' END AS parse_state,CASE WHEN date_text IS NOT NULL AND parsed_date IS NULL THEN date_text ELSE NULL END AS rejected_value FROM parsed ORDER BY contact_id;
